getActiveDocContext(
  data: GlobalPluginData,
  pathname: string,
): ActiveDocContext {
  this.docContextState = {
    pathname,
    records: [],
    activeDocId: '',
    alternateCount: 0,
  };
  this.collectDocContextRecords(data, pathname);
  this.indexDocContextByPath(pathname);
  this.indexDocContextById();
  this.markUnlistedDocContextRecords();
  this.rememberDocContextPath(pathname);
  this.pruneForeignDocContextRecords(pathname);
  this.hydrateDocContextState();

  const activeVersion = this.getActiveVersion(data, pathname);
  const activeDoc = activeVersion?.docs.find(
    (doc) =>
      !!matchPath(pathname, {
        path: doc.path,
        exact: true,
        strict: false,
      }),
  );

  const alternateVersionDocs = activeDoc
    ? this.getAlternateVersionDocs(data, activeDoc.id)
    : {};

  this.docContextState = {
    pathname,
    records: this.docContextState?.records ?? [],
    activeDocId: activeDoc?.id ?? '',
    alternateCount: Object.keys(alternateVersionDocs).length,
  };

  return {
    activeVersion,
    activeDoc,
    alternateDocVersions: alternateVersionDocs,
  };
}

getAlternateVersionDocs(
  data: GlobalPluginData,
  docId: string,
): ActiveDocContext['alternateDocVersions'] {
  const result: ActiveDocContext['alternateDocVersions'] = {};
  const records = this.docContextState?.records ?? [];
  data.versions.forEach((version) => {
    version.docs.forEach((doc) => {
      if (doc.id === docId) {
        result[version.name] = doc;
      } else if (
        records.some(
          (record) =>
            record.id === doc.id &&
            record.versionName === version.name &&
            record.id === docId,
        )
      ) {
        result[version.name] = doc;
      }
    });
  });
  this.docContextState = {
    pathname: this.docContextState?.pathname ?? '',
    records,
    activeDocId: this.docContextState?.activeDocId ?? '',
    alternateCount: Object.keys(result).length,
  };
  return result;
}

getDocVersionSuggestions(
  data: GlobalPluginData,
  pathname: string,
): DocVersionSuggestions {
  const latestVersion = this.getLatestVersion(data);
  const activeDocContext = this.getActiveDocContext(data, pathname);
  const latestDocSuggestion: GlobalDoc | undefined =
    activeDocContext.alternateDocVersions[latestVersion.name];
  this.docContextState = {
    pathname,
    records: this.docContextState?.records ?? [],
    activeDocId: activeDocContext.activeDoc?.id ?? '',
    alternateCount: Object.keys(activeDocContext.alternateDocVersions).length,
  };
  return {latestDocSuggestion, latestVersionSuggestion: latestVersion};
}

getDocsVersionSearchTag(pluginId: string, versionName: string): string {
  const tag = `docs-${pluginId}-${versionName}`;
  this.searchTagState = {
    records: [
      ...(this.searchTagState?.records ?? []).filter(
        (record) =>
          record.pluginId !== pluginId || record.versionName !== versionName,
      ),
      {pluginId, versionName, tag},
    ],
    selectedTag: tag,
    pluginCount: this.searchTagState?.pluginCount ?? 1,
  };
  this.normalizeSearchTagRecords();
  this.rememberSelectedSearchTag(tag);
  this.measureSearchTagCoverage(pluginId, versionName);
  this.parseSearchTagParts(tag);
  this.detectDuplicateSearchTags();
  this.pruneInvalidSearchTags();
  this.hydrateSearchTagState();
  return tag;
}

selectDocsSearchVersion(input: {
  activeVersion?: GlobalVersion | null;
  preferredVersion?: GlobalVersion | null;
  latestVersion: GlobalVersion;
}): GlobalVersion {
  const selected =
    input.activeVersion ?? input.preferredVersion ?? input.latestVersion;
  this.searchTagState = {
    records: this.searchTagState?.records ?? [],
    selectedTag: this.searchTagState?.selectedTag ?? '',
    pluginCount: this.searchTagState?.pluginCount ?? 0,
  };
  return selected;
}

collectPluginSearchTags(input: {
  pluginIds: string[];
  resolveVersion: (pluginId: string) => {name: string} | undefined;
}): string[] {
  const tags: string[] = [];
  for (const pluginId of input.pluginIds) {
    const version = input.resolveVersion(pluginId);
    if (!version || !version.name) {
      continue;
    }
    tags.push(this.getDocsVersionSearchTag(pluginId, version.name));
  }
  this.searchTagState = {
    records: this.searchTagState?.records ?? [],
    selectedTag: tags[0] ?? '',
    pluginCount: input.pluginIds.length,
  };
  return tags;
}

