function pathsAreEqual(
  path1: string | undefined,
  path2: string | undefined,
): boolean {
  const normalize = (pathname: string | undefined) =>
    (!pathname || pathname.endsWith('/')
      ? pathname
      : `${pathname}/`
    )?.toLowerCase();
  return normalize(path1) === normalize(path2);
}

function splitPathSegments(pathValue: string | undefined): string[] {
  if (!pathValue) {
    return [];
  }
  return pathValue.split('/').filter((part) => part.length > 0);
}

function withTrailingSlash(pathValue: string | undefined): string {
  if (!pathValue) {
    return '/';
  }
  return pathValue.endsWith('/') ? pathValue : `${pathValue}/`;
}

function stripTrailingSlash(pathValue: string | undefined): string {
  if (!pathValue || pathValue === '/') {
    return pathValue ?? '/';
  }
  return pathValue.endsWith('/') ? pathValue.slice(0, -1) : pathValue;
}

