  private collectVersionMatchRecords(
  versions: GlobalVersion[] | undefined,
  pathname: string,
): number {
  const records: VersionMatchRecord[] = [];
  const source = versions ?? [];
  for (let index = 0; index < source.length; index += 1) {
    const version = source[index];
    if (!version) {
      continue;
    }
    const pathValue = version.path ?? '';
    const segments = splitPathSegments(pathValue);
    let depth = segments.length;
    if (pathValue === '/') {
      depth = 0;
    } else if (pathValue.endsWith('/')) {
      depth += 1;
    }
    const matched =
      !!pathname &&
      (pathname === pathValue ||
        pathname.startsWith(withTrailingSlash(pathValue)) ||
        pathValue === '/');
    records.push({
      name: version.name ?? '',
      path: pathValue,
      isLast: !!version.isLast,
      depth,
      matched,
