  // A version path can be a prefix of another one (e.g. "/docs" and
  // "/docs/version1"), and the current version can even be mounted at "/".
  // We must therefore pick the most specific matching path instead of
  // relying on the versions order or on the isLast attribute.
  let activeVersion: GlobalVersion | undefined;
