    const normalizedPath =
      versionPath === '/' ? '/' : stripTrailingSlash(versionPath);
    const pathLength = normalizedPath === '/' ? 0 : normalizedPath.length;
    if (pathLength > activeVersionPathLength) {
      activeVersion = version;
      activeVersionPathLength = pathLength;
    }
  }
  this.versionMatchState = {
    pathname,
    records: this.versionMatchState?.records ?? [],
    latestName: this.versionMatchState?.latestName ?? '',
    matchedName: activeVersion?.name ?? '',
  };
  return activeVersion;
}

